 "content": "from collections import deque
from itertools import permutations


def _rectangles(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    rects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            rh, rw = r1-r0+1, c1-c0+1
            if rh < 3 or rw < 3:
                continue
            perimeter = {(y, x) for y in range(r0, r1+1) for x in range(c0, c1+1)
                         if y in (r0, r1) or x in (c0, c1)}
            if len(cells) == len(perimeter) and all(grid[y][x] == color for y, x in perimeter):
                rects.append((r0, r1, c0, c1, color))
    return rects


def transform(grid):
    h, w = len(grid), len(grid[0])
    rects = _rectangles(grid)
    if not rects:
        return [row[:] for row in grid]

    frame_cells = set()
    for r0, r1, c0, c1, _ in rects:
        frame_cells.update((y, x) for y in range(r0, r1+1) for x in range(c0, c1+1)
                           if y in (r0, r1) or x in (c0, c1))
    dot_counts = {}
    for y in range(h):
        for x in range(w):
            v = grid[y][x]
            if v and (y, x) not in frame_cells:
                dot_counts[v] = dot_counts.get(v, 0) + 1

    # Each rectangle receives the scattered color whose dot count best matches
    # the number of checkerboard cells in its empty interior.
    colors = list(dot_counts)
    targets = [((r1-r0-1)*(c1-c0-1)+1)//2 for r0, r1, c0, c1, _ in rects]
    best = None
    if len(colors) >= len(rects):
        for chosen in permutations(colors, len(rects)):
            score = sum(abs(dot_counts[col]-target) for col, target in zip(chosen, targets))
            if best is None or score < best[0]:
                best = (score, chosen)
    assigned = best[1] if best else [0] * len(rects)

    out = [[0] * w for _ in range(h)]
    for (r0, r1, c0, c1, border), fill in zip(rects, assigned):
        for y in range(r0, r1+1):
            for x in range(c0, c1+1):
                if y in (r0, r1) or x in (c0, c1):
                    out[y][x] = border
                elif (y-r0-1 + x-c0-1) % 2 == 0:
                    out[y][x] = fill
    return out
